package dev.raven.backup;
import java.io.*;import java.util.*;import org.json.*;
final class RestorePreview {
 static final long RESERVE=64L*1024*1024;
 static final class Budget {final Map<String,Long> needed=new LinkedHashMap<>();final Map<String,File> volumes;String paths="";Budget(BackupEngine e)throws IOException{volumes=ExternalScopes.volumes(e.c);}}
 static String mapping(JSONObject transaction)throws Exception{return transaction==null?"none":transaction.getString("package")+":"+(transaction.has("parts")?transaction.getJSONArray("parts").toString():"primary:data");}
 static Budget budget(BackupEngine e,LiveRestore.Plan p,JSONObject transaction,boolean review)throws Exception{
  Budget b=new Budget(e);long current=0,incoming=0;StringBuilder commands=new StringBuilder("set -eu\n"),paths=new StringBuilder("Replaces these locations:\n");JSONArray apps=p.manifest.getJSONArray("apps");
  for(int i=0;i<apps.length();i++){JSONObject app=apps.getJSONObject(i);String pkg=app.getString("package");JSONArray payloads=app.getJSONArray("payloads");for(int j=0;j<payloads.length();j++){JSONObject part=payloads.getJSONObject(j);incoming=Math.addExact(incoming,part.getLong("bytes"));String path=LiveRestore.data(pkg,part.getString("domain"));paths.append(path).append(" · ").append(TransferProgress.size(part.getLong("bytes"))).append(" archive payload\n");commands.append("[ ! -L ").append(BackupEngine.q(path)).append(" ]\nif [ -d ").append(BackupEngine.q(path)).append(" ]; then du -sk ").append(BackupEngine.q(path)).append("; fi\n");}}
  commands.append("echo RAVEN_PREVIEW_OK\n");File job=e.job();String output;try{output=e.run(job,commands.toString(),false).trim();}finally{e.clean(job);}if(!output.endsWith("RAVEN_PREVIEW_OK"))throw new IOException("Cannot estimate recovery space");output=output.substring(0,output.length()-"RAVEN_PREVIEW_OK".length()).trim();if(!output.isEmpty())for(String line:output.split("\\r?\\n"))current=Math.addExact(current,Math.multiplyExact(Long.parseLong(line.trim().split("\\s+",2)[0]),1024));
  long privateNeed=Math.addExact(RESERVE,Math.multiplyExact(Math.addExact(current,1024*1024),4));if(review&&p.metadataOnly)privateNeed=Math.addExact(privateNeed,incoming);b.needed.put("primary",privateNeed);
  if(transaction!=null){if(transaction.has("parts")){JSONArray parts=transaction.getJSONArray("parts");for(int i=0;i<parts.length();i++){JSONObject part=parts.getJSONObject(i);String volume=part.getString("volume");b.needed.put(volume,Math.addExact(b.needed.getOrDefault(volume,RESERVE),part.getLong("bytes")));paths.append((volume.equals("primary")?"Internal storage":"SD card "+volume)+"/Android/"+part.getString("kind")+"/"+transaction.getString("package")+(part.getString("kind").equals("data")?"/files":"")).append(" · ").append(TransferProgress.size(part.getLong("bytes"))).append(" archive payload\n");}}else{long bytes=ExternalData.metadata(p.manifest).getLong("bytes");b.needed.put("primary",Math.addExact(b.needed.get("primary"),bytes));paths.append("Internal storage/Android/data/"+transaction.getString("package")+"/files\n");}}
  b.paths=paths.toString();return b;
 }
 static String describe(BackupEngine e,LiveRestore.Plan p)throws Exception{JSONObject transaction=ExternalData.transaction(e,p);p.reviewedMapping=mapping(transaction);Budget b=budget(e,p,transaction,true);StringBuilder text=new StringBuilder("\n"+b.paths+"\nFree-space estimate for temporary staging and recovery:\n");for(Map.Entry<String,Long> n:b.needed.entrySet()){File volume=n.getKey().equals("primary")?e.c.getFilesDir():b.volumes.get(n.getKey());if(volume==null)throw new IOException("Restore volume is unavailable");text.append(n.getKey().equals("primary")?"Internal storage":("SD card "+n.getKey())).append(": about ").append(TransferProgress.size(n.getValue())).append(" needed; ").append(TransferProgress.size(volume.getUsableSpace())).append(" free\n");}return text.append("Estimates include recovery overhead; actual size may vary. Each queued app is rechecked before replacement. Unlisted app-storage folders stay unchanged.\n").toString();}
 static JSONObject require(BackupEngine e,LiveRestore.Plan p)throws Exception{JSONObject t=ExternalData.transaction(e,p);if(p.reviewedMapping!=null&&!p.reviewedMapping.equals(mapping(t)))throw new IOException("Restore storage mapping changed. Review this backup again.");Budget b=budget(e,p,t,false);for(Map.Entry<String,Long> n:b.needed.entrySet()){File volume=n.getKey().equals("primary")?e.c.getFilesDir():b.volumes.get(n.getKey());if(volume==null||volume.getUsableSpace()<n.getValue())throw new IOException("Insufficient free space for safe restore on "+n.getKey()+". Need about "+TransferProgress.size(n.getValue())+" free.");}return t;}
}
